"use strict";(self.webpackChunkailmanac=self.webpackChunkailmanac||[]).push([["147"],{80529(e,i,n){n.r(i),n.d(i,{metadata:()=>o,default:()=>p,frontMatter:()=>r,contentTitle:()=>l,toc:()=>c,assets:()=>s});var o=JSON.parse('{"id":"models/latent-reasoning-hybrid-agents","title":"Ragionamento latente: agenti che pensano senza parole","description":"HybridAgent \xe8 il primo agente open-weight che fa la maggior parte del suo pensiero come stati nascosti invece che come token: 170-183 passi latenti per compito contro ~300 token di testo, 35,5-54,7% di token in meno, 2,7-3,7x pi\xf9 economico. Il meccanismo (un adapter da ~10M parametri), il motivo per cui va in loop infinito se lo carichi in llama.cpp e perch\xe9 \'i pensieri latenti ispezionabili\' \xe8 l\'affermazione pi\xf9 contestata del paper.","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/models/latent-reasoning-hybrid-agents.mdx","sourceDirName":"models","slug":"/models/latent-reasoning-hybrid-agents","permalink":"/ailmanac/it/docs/models/latent-reasoning-hybrid-agents","draft":false,"unlisted":false,"editUrl":"https://github.com/derob98/ailmanac/tree/main/docs/models/latent-reasoning-hybrid-agents.mdx","tags":[],"version":"current","sidebarPosition":23.1,"frontMatter":{"sidebar_position":23.1,"title":"Ragionamento latente: agenti che pensano senza parole","description":"HybridAgent \xe8 il primo agente open-weight che fa la maggior parte del suo pensiero come stati nascosti invece che come token: 170-183 passi latenti per compito contro ~300 token di testo, 35,5-54,7% di token in meno, 2,7-3,7x pi\xf9 economico. Il meccanismo (un adapter da ~10M parametri), il motivo per cui va in loop infinito se lo carichi in llama.cpp e perch\xe9 \'i pensieri latenti ispezionabili\' \xe8 l\'affermazione pi\xf9 contestata del paper.","keywords":["latent reasoning","HybridAgent","HybridLink","Coconut latent reasoning","Soft Thinking","continuous chain of thought","neuralese","chain-of-thought monitorability","token reduction agents","Together AI HybridAgent","open weight agent model"]},"sidebar":"docs","previous":{"title":"DeepInfer: il motore di inferenza di DeepSeek, letto onestamente","permalink":"/ailmanac/it/docs/models/deepinfer-deepseek-inference-engine"},"next":{"title":"Il livello di memoria di terze parti: come funziona davvero claude-mem","permalink":"/ailmanac/it/docs/models/agent-memory-layer-claude-mem"}}'),a=n(74848),t=n(28453);let r={sidebar_position:23.1,title:"Ragionamento latente: agenti che pensano senza parole",description:"HybridAgent \xe8 il primo agente open-weight che fa la maggior parte del suo pensiero come stati nascosti invece che come token: 170-183 passi latenti per compito contro ~300 token di testo, 35,5-54,7% di token in meno, 2,7-3,7x pi\xf9 economico. Il meccanismo (un adapter da ~10M parametri), il motivo per cui va in loop infinito se lo carichi in llama.cpp e perch\xe9 'i pensieri latenti ispezionabili' \xe8 l'affermazione pi\xf9 contestata del paper.",keywords:["latent reasoning","HybridAgent","HybridLink","Coconut latent reasoning","Soft Thinking","continuous chain of thought","neuralese","chain-of-thought monitorability","token reduction agents","Together AI HybridAgent","open weight agent model"]},l,s={},c=[{value:"Il meccanismo: un passaggio saltato",id:"il-meccanismo-un-passaggio-saltato",level:2},{value:"Cosa ne fa un <em>agente</em>, non solo un ragionatore",id:"cosa-ne-fa-un-agente-non-solo-un-ragionatore",level:2},{value:"I numeri",id:"i-numeri",level:2},{value:"Il tranello che ha morso tutti il primo giorno",id:"il-tranello-che-ha-morso-tutti-il-primo-giorno",level:2},{value:"L&#39;affermazione contestata: i pensieri latenti sono davvero ispezionabili?",id:"laffermazione-contestata-i-pensieri-latenti-sono-davvero-ispezionabili",level:2},{value:"La parte che meritava pi\xf9 attenzione di quella ricevuta",id:"la-parte-che-meritava-pi\xf9-attenzione-di-quella-ricevuta",level:3},{value:"Dove si colloca nel campo",id:"dove-si-colloca-nel-campo",level:2},{value:"Dovresti gi\xe0 occupartene?",id:"dovresti-gi\xe0-occupartene",level:2},{value:"Fonti e approfondimenti",id:"fonti-e-approfondimenti",level:2},{value:"Prossimi passi",id:"prossimi-passi",level:2}];function d(e){let i={a:"a",code:"code",em:"em",h2:"h2",h3:"h3",li:"li",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,t.R)(),...e.components},{Callout:n,Flashcards:o,LevelBadge:r,PromptCard:l,Quiz:s,Steps:c,VerifyNote:d}=i;return n||u("Callout",!0),o||u("Flashcards",!0),r||u("LevelBadge",!0),l||u("PromptCard",!0),s||u("Quiz",!0),c||u("Steps",!0),d||u("VerifyNote",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(r,{level:"advanced"}),"\n",(0,a.jsxs)(i.p,{children:["Ogni modello di ragionamento che hai usato pensa scrivendo. Extended thinking, blocchi ",(0,a.jsx)(i.code,{children:"<thinking>"}),", scratchpad, tracce ReAct: la deliberazione del modello \xe8 un flusso di token, il che significa che puoi leggerla, e significa che paghi ogni singola parola."]}),"\n",(0,a.jsxs)(i.p,{children:["Il ",(0,a.jsx)(i.strong,{children:"ragionamento latente"})," chiede cosa succede se si tolgono le parole. Invece di campionare un token dall'ultimo stato nascosto e reinserire l'embedding del token, reinserisci lo ",(0,a.jsx)(i.em,{children:"stato nascosto stesso"}),". Nessuna proiezione sul vocabolario, nessun campionamento, nessun testo. Il modello continua a pensare; il pensiero ora \xe8 un vettore."]}),"\n",(0,a.jsxs)(i.p,{children:["\xc8 stata una curiosit\xe0 di ricerca dai tempi di Coconut di Meta, a fine 2024. Il ",(0,a.jsx)(i.strong,{children:"13 ottobre 2026"})," \xe8 diventata qualcosa che puoi scaricare: ",(0,a.jsx)(i.a,{href:"https://arxiv.org/abs/2610.18861",children:"HybridAgent"})," di Together AI \xe8 il primo ",(0,a.jsx)(i.em,{children:"agente"}),' a ragionamento latente: pensa in stati nascosti, chiama un interprete Python e un motore di ricerca tramite testo, ed \xe8 distribuito come checkpoint 8B e 14B con licenza MIT. \xc8 arrivato in prima pagina su Hacker News con 396 punti e 192 commenti, e i commenti si sono divisi quasi esattamente a met\xe0 tra "questa \xe8 la strada" e "hai appena cancellato l\'unica cosa che potevamo verificare".']}),"\n",(0,a.jsx)(i.p,{children:"Entrambi i campi hanno ragione su qualcosa. Questa pagina copre il meccanismo, i numeri, il motivo per cui diversi tester hanno ottenuto un loop infinito invece di una risposta, e l'unica affermazione del paper che non dovresti prendere per buona."}),"\n",(0,a.jsx)(n,{type:"objectives",items:["Spiegare il ragionamento latente in una frase: reinserire lo stato nascosto come prossimo embedding di input invece di proiettarlo su un token","Leggere la formula di HybridLink e capire perch\xe9 un adapter da ~10M parametri \xe8 tutto ci\xf2 che separa un modello di testo da uno latente","Citare la vera suddivisione: 170-183 passi latenti per istanza contro ~302 token di testo, dove un agente solo testo ne spende ~596","Sapere perch\xe9 caricare questi pesi in llama.cpp o in Transformers semplice d\xe0 un modello di testo in loop, non un agente latente","Sostenere entrambi i lati dell'affermazione sull'ispezionabilit\xe0, incluso il test causale del paper stesso che mostra che i pensieri latenti portano il 44,9-51,3% dell'accuratezza","Collocare HybridAgent rispetto a Coconut e Soft Thinking, e sapere quale dei tre non richiede alcun addestramento"]}),"\n",(0,a.jsx)(d,{lastVerified:"2026-10-19",source:"https://arxiv.org/abs/2610.18861",children:(0,a.jsxs)(i.p,{children:["HybridAgent \xe8 stato inviato il 13 ottobre 2026 e il repository ha pochi giorni (216 stelle, 28 fork al momento della scrittura). Numeri di benchmark, nomi dei checkpoint, conteggi dei download e la storia del serving si muoveranno tutti. Il ",(0,a.jsx)(i.strong,{children:"meccanismo"})," (stati nascosti come mezzo di ragionamento, un piccolo adapter come ponte e il compromesso sulla monitorabilit\xe0 che impone) \xe8 la parte duratura. Ricontrolla il repo prima di basarti su un comando specifico."]})}),"\n",(0,a.jsx)(i.h2,{id:"il-meccanismo-un-passaggio-saltato",children:"Il meccanismo: un passaggio saltato"}),"\n",(0,a.jsxs)(i.p,{children:["Prendi un decoder standard. Al passo ",(0,a.jsx)(i.code,{children:"t"})," produce uno stato nascosto dell'ultimo layer ",(0,a.jsx)(i.code,{children:"h_t"}),", lo proietta attraverso la matrice di unembedding in logit sul vocabolario, campiona un token, cerca quel token nella tabella degli embedding e reinserisce l'embedding come input ",(0,a.jsx)(i.code,{children:"t+1"}),"."]}),"\n",(0,a.jsxs)(i.p,{children:["Quel viaggio di andata e ritorno attraverso il vocabolario \xe8 un collo di bottiglia in senso letteralmente informazionale. Uno stato nascosto in un moderno modello 8B \xe8 qualche migliaio di numeri in virgola mobile. Un token \xe8 una scelta tra ~150.000 opzioni, circa 17 bit. ",(0,a.jsx)(i.strong,{children:"Campionare un token butta via quasi tutto ci\xf2 che lo stato nascosto conteneva"})," e conserva il solo simbolo discreto che un umano pu\xf2 leggere."]}),"\n",(0,a.jsxs)(i.p,{children:["Il ragionamento latente salta il viaggio. Reinserisci ",(0,a.jsx)(i.code,{children:"h_t"})," direttamente. Il successivo forward pass del modello dipende dall'intero stato continuo e non dal riassunto a 17 bit di esso."]}),"\n",(0,a.jsxs)(i.p,{children:["Il problema \xe8 che ",(0,a.jsx)(i.code,{children:"h_t"})," vive nello spazio di ",(0,a.jsx)(i.em,{children:"output"})," e il modello si aspetta qualcosa dallo spazio degli ",(0,a.jsx)(i.em,{children:"embedding di input"}),". Le distribuzioni non coincidono, e inserire l'una nell'altra ingenuamente produce spazzatura. HybridLink \xe8 la correzione, ed \xe8 quasi imbarazzantemente piccola:"]}),"\n",(0,a.jsx)(i.pre,{children:(0,a.jsx)(i.code,{children:"e_{t+1} = h_t + W_2 \xb7 \u03C3(W_1 \xb7 h_t)\n"})}),"\n",(0,a.jsxs)(i.p,{children:["Una MLP a due layer con connessione residua. Il residuo \xe8 la parte portante: porta ",(0,a.jsx)(i.code,{children:"h_t"})," invariato cos\xec che la semantica sopravviva, mentre il ramo MLP lo spinge nella distribuzione di input. Il paper lo stima in circa ",(0,a.jsx)(i.code,{children:"2 \xb7 d_h\xb2"})," parametri, cio\xe8 circa ",(0,a.jsx)(i.strong,{children:"10M per un backbone da 4B"}),". Tre ordini di grandezza pi\xf9 piccolo del modello che governa."]}),"\n",(0,a.jsx)(n,{type:"key",items:["Un token \xe8 ~17 bit. Uno stato nascosto \xe8 migliaia di float. Campionare \xe8 una compressione con perdita del pensiero stesso del modello, eseguita a ogni passo.","HybridLink \xe8 e_{t+1} = h_t + W_2\xb7\u03C3(W_1\xb7h_t): una MLP residua a due layer, ~10M parametri per un modello da 4B. Quell'adapter \xe8 l'intero ponte.","La connessione residua non \xe8 decorazione. L'ablazione degli autori mostra che il disegno residuo d\xe0 guadagni costanti su tutti e tre i benchmark a valle."]}),"\n",(0,a.jsxs)(i.h2,{id:"cosa-ne-fa-un-agente-non-solo-un-ragionatore",children:["Cosa ne fa un ",(0,a.jsx)(i.em,{children:"agente"}),", non solo un ragionatore"]}),"\n",(0,a.jsx)(i.p,{children:"Coconut e Soft Thinking fanno entrambi ragionamento latente. Nessuno dei due pu\xf2 chiamare un tool, perch\xe9 i tool sono un'interfaccia di testo: emetti una chiamata di funzione, qualcosa gira, torna del testo. Un modello nel mezzo di un pensiero latente non ha token da emettere e nessun posto dove mettere il risultato."}),"\n",(0,a.jsx)(i.p,{children:"HybridAgent lo risolve con due pezzi."}),"\n",(0,a.jsx)(c,{items:[{title:"I token \xe0ncora segnano il confine di modalit\xe0",body:"Il tokenizer acquisisce <latent> e </latent>. Il modello emette <latent> in modalit\xe0 testo per entrare in modalit\xe0 latente; HybridLink poi reinserisce in ciclo gli stati nascosti. La modalit\xe0 latente si chiude quando il token pi\xf9 vicino allo stato corrente (proiettato) \xe8 </latent>: \xe8 la geometria stessa del modello a decidere quando ha pensato abbastanza. Non c'\xe8 un budget latente fisso. Coconut, al contrario, ha scelto un numero costante di pensieri latenti perch\xe9 lasciar decidere a un classificatore non andava meglio."},{title:"Una memoria di lavoro continua porta tutto attraverso i turni",body:"Invece di serializzare il turno in testo e ricodificarlo, HybridAgent accoda voci KV (M\u207D\xb9\u207E = M\u207D\u2070\u207E \u2295 [K\u2264t, V\u2264t]), cos\xec span di testo, span latenti e output dei tool si accumulano in un'unica cache. I pensieri latenti non hanno forma testuale, quindi non ci sarebbe nulla da ricodificare: la KV cache \xc8 la trascrizione. Per questo il paper chiama il contesto ibrido 'lossless' tra i turni."},{title:"Due fasi di addestramento insegnano il cambio di modalit\xe0",body:"HybridSFT insegna al backbone a coordinarsi con HybridLink su sequenze ibride integrate con tool. Poi HybridRL lo fa scalare con la ricompensa r(\u03C4) = r_correct + r_format + r_tool. Nota cosa manca: NON c'\xe8 alcun termine di ricompensa per l'uso della modalit\xe0 latente. L'equilibrio testo/latente \xe8 emergente, non incentivato."},{title:"I tool restano ordinari",body:"Un interprete Python in sandbox e un motore di ricerca dal vivo (Tavily nella configurazione del paper), limitati a 10 chiamate per traiettoria con i primi 10 snippet per query. Niente nel livello dei tool \xe8 esotico: l'agente torna al testo per chiamarli, esattamente come farebbe ReAct."}]}),"\n",(0,a.jsxs)(i.p,{children:["Il dettaglio di addestramento da rubare \xe8 la ",(0,a.jsx)(i.strong,{children:"supervisione auto-condizionata"}),". Il teacher forcing ingenuo inserisce embedding latenti ground-truth durante l'addestramento, cos\xec in inferenza il modello incontra per la prima volta i propri output di HybridLink e deriva. La correzione \xe8 uno schema a due passaggi: il primo passaggio fa teacher forcing sulla sequenza ibrida ground-truth, il secondo rigioca la sequenza identica con gli embedding latenti ",(0,a.jsx)(i.em,{children:"generati dal modello stesso"})," sostituiti. La Tabella 3 la riporta come valore ",(0,a.jsx)(i.strong,{children:"30,5% in media"})," su AIME25/26 e MATH500 rispetto all'attivare HybridLink senza di essa. \xc8 lo stesso problema di exposure bias che lo scheduled sampling affronta nei modelli di sequenza, e la stessa forma di correzione."]}),"\n",(0,a.jsx)(i.h2,{id:"i-numeri",children:"I numeri"}),"\n",(0,a.jsx)(n,{type:"warning",items:["Questi sono i numeri degli autori stessi sul loro harness, vecchi di pochi giorni, senza replica indipendente. Leggili come un'affermazione, non come una misurazione su cui contare.","Il titolo '10,4% di miglioramento' \xe8 una media su 3 scale di modello e 11 benchmark contro un mix di baseline. Per benchmark va da +1,8 punti a +42,5."]}),"\n",(0,a.jsxs)(i.table,{children:[(0,a.jsx)(i.thead,{children:(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.th,{children:"Affermazione"}),(0,a.jsx)(i.th,{children:"Cifra"})]})}),(0,a.jsxs)(i.tbody,{children:[(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Guadagno medio di prestazioni"}),(0,a.jsxs)(i.td,{children:[(0,a.jsx)(i.strong,{children:"+10,4%"})," su 3 scale, 11 benchmark"]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Riduzione dei token"}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.strong,{children:"35,5-54,7%"})})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Velocit\xe0 di inferenza"}),(0,a.jsxs)(i.td,{children:[(0,a.jsx)(i.strong,{children:"1,8x-2,6x"})," pi\xf9 veloce"]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Costo"}),(0,a.jsxs)(i.td,{children:[(0,a.jsx)(i.strong,{children:"2,7x-3,7x"})," pi\xf9 economico"]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Token di testo per istanza (8B)"}),(0,a.jsxs)(i.td,{children:[(0,a.jsx)(i.strong,{children:"~302"}),", contro i ",(0,a.jsx)(i.strong,{children:"~596"})," di un agente di testo"]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:"Passi latenti per istanza"}),(0,a.jsx)(i.td,{children:(0,a.jsx)(i.strong,{children:"170-183"})})]})]})]}),"\n",(0,a.jsxs)(i.p,{children:["Le ultime due righe sono quelle che spiegano davvero l'architettura. HybridAgent emette circa met\xe0 del testo di un agente solo testo, ed esegue 170-183 forward pass aggiuntivi che non producono alcun testo. ",(0,a.jsx)(i.strong,{children:"Non pensa di meno. Pensa in un mezzo che non fattura a parola."})]}),"\n",(0,a.jsx)(i.p,{children:"Questo dice anche da dove viene il risparmio di costo, e da dove no. Un passo latente \xe8 comunque un intero forward pass: stessi FLOP, stessa latenza, stesso traffico di memoria della generazione di un token. Il risparmio non \xe8 calcolo gratuito. Viene da (a) non pagare l'overhead di decode-and-re-embed, (b) una sequenza KV molto pi\xf9 corta perch\xe9 gli span latenti sono densi invece che esplicitati, e (c) meno passi totali per arrivare a una risposta. Se la tua fattura \xe8 dominata dal prefill di un grande contesto statico, il ragionamento latente non fa nulla per te."}),"\n",(0,a.jsxs)(i.p,{children:["Contro le baseline latenti i divari sono grandi: su GAIA Level 1 il paper riporta ",(0,a.jsx)(i.strong,{children:"+39,8% su Coconut"})," e ",(0,a.jsx)(i.strong,{children:"+28,2% su Soft Thinking"}),", e circa +41-42% su WebWalker per entrambi. \xc8 meno una conferma del ragionamento di HybridAgent che un promemoria che Coconut e Soft Thinking non sono mai stati costruiti per tenere insieme un ciclo di tool a pi\xf9 turni. Contro le baseline ",(0,a.jsx)(i.em,{children:"testuali"})," i margini sono modesti e onesti: AIME25 39,2% contro il 37,1% di ARPO, MATH500 84,6% contro 82,8%, MuSiQue 32,0% contro 28,5%."]}),"\n",(0,a.jsx)(i.h2,{id:"il-tranello-che-ha-morso-tutti-il-primo-giorno",children:"Il tranello che ha morso tutti il primo giorno"}),"\n",(0,a.jsx)(i.p,{children:"Diverse persone nel thread di lancio hanno riferito lo stesso fallimento: chiedi all'8B \"chi \xe8 il papa?\" e va in loop all'infinito. Un tester ha visto lo stesso loop con il 14B in llama.cpp sia a 8 bit sia a 16 bit, e ha concluso che il problema fosse llama.cpp e non il modello."}),"\n",(0,a.jsxs)(i.p,{children:["Quella diagnosi \xe8 quasi certamente giusta, e la model card dice perch\xe9 in una riga: ",(0,a.jsx)(i.strong,{children:"il caricamento standard con Transformers produce una variante solo testo"}),", perch\xe9 il comportamento ibrido vive in ",(0,a.jsx)(i.code,{children:"adapter.pt"})," / ",(0,a.jsx)(i.code,{children:"adapter_config.json"})," (i pesi di HybridLink) pi\xf9 il motore di generazione personalizzato nel repo."]}),"\n",(0,a.jsxs)(i.p,{children:["Pensa a cosa fa un runtime generico con questi pesi. Il tokenizer ha ",(0,a.jsx)(i.code,{children:"<latent>"})," e ",(0,a.jsx)(i.code,{children:"</latent>"}),". Il backbone addestrato ha imparato a emettere ",(0,a.jsx)(i.code,{children:"<latent>"})," e poi ad aspettarsi che HybridLink prenda il controllo. In llama.cpp o in ",(0,a.jsx)(i.code,{children:"AutoModelForCausalLM"})," semplice, nulla prende il controllo. Non c'\xe8 alcun componente che reinserisca gli stati nascosti e nessun componente che valuti la condizione di chiusura basata sul vicino pi\xf9 prossimo. Il modello entra in una modalit\xe0 che non esiste e non ne trova mai l'uscita."]}),"\n",(0,a.jsx)(n,{type:"warning",items:["Questo \xe8 un modello a forma di stack di inferenza, non a forma di pesi. Conversione GGUF, vLLM, Ollama e Transformers semplice non riprodurranno il comportamento del paper: non possono, perch\xe9 HybridLink non \xe8 nel grafo.","La generazione infinita su una domanda banale \xe8 la firma di un HybridLink mancante, non di un checkpoint rotto.","Il README non documenta alcun percorso di serving oltre al motore di inferenza batch del repo. Tratta 'posso servirlo?' come senza risposta, non come un s\xec."]}),"\n",(0,a.jsx)(l,{title:"L'unico percorso che esegue la vera architettura",children:`git clone https://github.com/togethercomputer/HybridAgent.git && cd HybridAgent
conda create -n hybridagent python=3.11 -y && conda activate hybridagent
pip install torch==2.11.0 --index-url https://download.pytorch.org/whl/cu128
pip install -r requirements.txt && pip install -e .
cp .env.example .env   # set TAVILY_API_KEY \u{2014} the search tool needs it

python -m hybrid_inference.run_batch \\
--model togethercomputer/HybridAgent-8B-Agentic \\
--input examples/questions.jsonl \\
--output outputs/results.jsonl --num_samples 4`}),"\n",(0,a.jsxs)(i.p,{children:["Se vuoi ",(0,a.jsx)(i.em,{children:"vedere"})," i pensieri latenti invece di misurarli con benchmark, il repo include un viewer dedicato che rende un'esecuzione come report HTML con pensieri in pseudo-testo intercalati a chiamate di tool e osservazioni:"]}),"\n",(0,a.jsx)(l,{title:"Rendi i pensieri latenti di una traiettoria come pseudo-testo leggibile",children:`python -m interpretable_latent_mode \\
--model togethercomputer/HybridAgent-14B-Agentic \\
--question "Which of these two papers reports a larger token reduction, and by how much?" \\
--output report.html`}),"\n",(0,a.jsxs)(i.p,{children:["L'addestramento \xe8 un'altra scala di impegno. HybridSFT richiede ",(0,a.jsx)(i.strong,{children:"8-16 GPU"}),"; HybridRL richiede ",(0,a.jsx)(i.strong,{children:"32 GPU su 4 nodi"}),". Non \xe8 un fine-tuning che si esegue su una workstation."]}),"\n",(0,a.jsx)(i.h2,{id:"laffermazione-contestata-i-pensieri-latenti-sono-davvero-ispezionabili",children:"L'affermazione contestata: i pensieri latenti sono davvero ispezionabili?"}),"\n",(0,a.jsx)(i.p,{children:"La mossa retorica pi\xf9 forte del paper \xe8 che il ragionamento latente non ti costa trasparenza. Ogni passo latente pu\xf2 essere letto come pseudo-testo, prendendo lo stato che HybridLink ha prodotto e trovandone il vicino pi\xf9 prossimo nella tabella degli embedding per similarit\xe0 coseno. La Figura 2 mostra che il risultato \xe8 leggibile e specifico del contesto, e resta semanticamente allineato con il ragionamento testuale circostante."}),"\n",(0,a.jsxs)(i.p,{children:["\xc8 una capacit\xe0 reale, e va oltre ci\xf2 che offriva Coconut. \xc8 anche l'anello pi\xf9 debole dell'argomento, per un motivo che un commentatore ha espresso con precisione: la decodifica per vicino pi\xf9 prossimo ",(0,a.jsx)(i.strong,{children:'"loses meaning where the model is expressing combinations of tokens in a vector."'})," L'intera premessa del ragionamento latente \xe8 che uno stato nascosto porta pi\xf9 di quanto qualsiasi token singolo possa portare. Leggerlo ",(0,a.jsx)(i.em,{children:"come"})," token singolo scarta necessariamente il surplus: lo stesso surplus che rendeva la tecnica degna di essere fatta."]}),"\n",(0,a.jsxs)(i.p,{children:["L'esperimento del paper stesso lo rende concreto ed \xe8 il risultato pi\xf9 interessante al suo interno. La Tabella 5 esegue interventi causali: corrompi i pensieri latenti e l'accuratezza cala del ",(0,a.jsx)(i.strong,{children:"44,9-51,3%"}),". Il flusso latente non \xe8 un canale laterale decorativo. Porta circa met\xe0 della risoluzione dei problemi del modello."]}),"\n",(0,a.jsxs)(i.p,{children:["Quindi le due affermazioni, ",(0,a.jsx)(i.em,{children:"i pensieri latenti sono portanti"})," e ",(0,a.jsx)(i.em,{children:"i pensieri latenti sono leggibili fedelmente come token singoli"}),", sono in tensione. Una lettura che comprimesse un vettore portante fino alla sua parola pi\xf9 vicina senza perdere nulla significherebbe che il vettore non ha mai avuto bisogno di essere un vettore."]}),"\n",(0,a.jsxs)(i.p,{children:["Conta oltre l'estetica dell'interpretabilit\xe0, perch\xe9 leggere la chain of thought \xe8 oggi un controllo di sicurezza attivo. Il position paper intra-laboratorio del 2025 ",(0,a.jsx)(i.strong,{children:(0,a.jsx)(i.a,{href:"https://arxiv.org/abs/2507.11473",children:"Chain of Thought Monitorability"})}),", con 41 autori tra cui Yoshua Bengio, Anca Dragan e Dan Hendrycks, di Anthropic, OpenAI, Google DeepMind e altri, sostiene proprio che i modelli di ragionamento esternalizzano la loro deliberazione in forma leggibile, che monitorarla \xe8 una vera opportunit\xe0 di supervisione, e che l'opportunit\xe0 \xe8 ",(0,a.jsx)(i.strong,{children:"fragile"}),": cambi di architettura possono rimuovere il substrato monitorabile come effetto collaterale di una decisione di efficienza. Il ragionamento latente \xe8 l'esempio da manuale di quell'effetto collaterale. Il nome informale del punto d'arrivo \xe8 ",(0,a.jsx)(i.strong,{children:"neuralese"}),": ragionamento senza alcuna traccia leggibile da un umano."]}),"\n",(0,a.jsxs)(i.p,{children:['Il thread di lancio ha fatto emergere anche la versione pi\xf9 sottile in fase di addestramento, che i commentatori hanno etichettato con la frase di Zvi Mowshowitz "the Most Forbidden Technique": se ',(0,a.jsx)(i.em,{children:"ottimizzi contro"})," un monitor della chain of thought durante l'RL, non rimuovi il comportamento cattivo, rimuovi la sua visibilit\xe0. Il ragionamento latente arriva a una destinazione simile da un'altra strada: non insegnando al modello a nascondere il suo pensiero, ma spostando il pensiero dove non c'\xe8 nulla da nascondere."]}),"\n",(0,a.jsx)(i.h3,{id:"la-parte-che-meritava-pi\xf9-attenzione-di-quella-ricevuta",children:"La parte che meritava pi\xf9 attenzione di quella ricevuta"}),"\n",(0,a.jsxs)(i.p,{children:["L'inquadramento del paper stesso, nella sezione Discussion, \xe8 il dettaglio che la maggior parte della copertura ha saltato. I pensieri latenti esistono solo come stati nascosti, leggibili tramite HybridLink, e l'argomento offerto \xe8 che questa \xe8 una ",(0,a.jsx)(i.em,{children:"funzionalit\xe0"}),": un provider che lo distribuisce pu\xf2 eseguire una valutazione di sicurezza sull'intera traccia di ragionamento mentre la traccia non lascia mai la sua infrastruttura, cos\xec il ragionamento non pu\xf2 trapelare agli utenti come pu\xf2 il pensiero testuale."]}),"\n",(0,a.jsxs)(i.p,{children:["Leggilo due volte. \xc8 una posizione coerente: le tracce di ragionamento sono davvero un asset competitivo e una superficie di esfiltrazione, ed \xe8 per questo che tanti provider riassumono invece di esporre l'extended thinking. Ma la struttura che descrive \xe8 una ",(0,a.jsx)(i.strong,{children:"trasparenza asimmetrica per costruzione"}),": il laboratorio che detiene l'adapter pu\xf2 leggere i pensieri, e nessun altro pu\xf2. Per un checkpoint con licenza MIT che include il proprio adapter, l'asimmetria \xe8 irrilevante: la chiave ce l'hai tu. Per un modello di frontiera ospitato e costruito allo stesso modo, non lo sarebbe."]}),"\n",(0,a.jsx)(i.h2,{id:"dove-si-colloca-nel-campo",children:"Dove si colloca nel campo"}),"\n",(0,a.jsx)(o,{cards:[{front:"Ragionamento latente, in una frase",back:"Reinserire lo stato nascosto dell'ultimo layer come prossimo embedding di input invece di proiettarlo su logit, campionare un token e ri-embeddare quel token. Il pensiero resta un vettore."},{front:"Coconut (Meta FAIR, dic 2024)",back:"Chain of Continuous Thought: il punto d'origine. arXiv 2412.06769. Ha mostrato un comportamento emergente di ricerca in ampiezza e ha battuto la CoT su compiti logici ricchi di backtracking come ProsQA con meno token di pensiero. Usa un numero costante di pensieri latenti; nessun accesso a tool."},{front:"Soft Thinking (mag 2025)",back:"arXiv 2505.15778. Senza addestramento: il 'concept token' \xe8 la miscela pesata per probabilit\xe0 degli embedding dei token, cos\xec ottieni uno stato continuo senza mettere a punto nulla. Aggiunge un meccanismo Cold Stop per fermarsi quando \xe8 troppo sicuro. Il modo pi\xf9 economico di provare il ragionamento latente."},{front:"HybridAgent (Together AI, ott 2026)",back:"arXiv 2610.18861. Primo AGENTE a ragionamento latente: pensiero latente pi\xf9 chiamate a tool in testo in un'unica generazione, una memoria di lavoro KV continua tra i turni, checkpoint MIT 8B/14B su Qwen3-Base, addestrati con HybridSFT poi HybridRL."},{front:"HybridLink",back:"e_{t+1} = h_t + W_2\xb7\u03C3(W_1\xb7h_t). Una MLP residua a due layer che mappa gli stati nascosti di output nello spazio degli embedding di input. ~2\xb7d_h\xb2 parametri (~10M per un modello da 4B). Distribuito come adapter.pt: senza di esso il checkpoint \xe8 un modello di testo che va in loop."},{front:"Token \xe0ncora",back:"<latent> e </latent>. Il modello emette <latent> per entrare in modalit\xe0 latente. La modalit\xe0 latente si chiude quando il token pi\xf9 vicino allo stato corrente \xe8 </latent>, quindi il modello decide il proprio budget di pensiero per ogni span."},{front:"Memoria di lavoro continua",back:"M\u207D\xb9\u207E = M\u207D\u2070\u207E \u2295 [K\u2264t, V\u2264t]. Le voci KV per span di testo, latenti e di tool si accumulano direttamente, senza passaggio di serializzazione e ricodifica. Necessario perch\xe9 i pensieri latenti non hanno forma testuale da ricodificare."},{front:"Supervisione auto-condizionata",back:"Addestramento a due passaggi: il primo fa teacher forcing sui latenti ground-truth, il secondo rigioca la stessa sequenza con i latenti generati dal modello stesso. Chiude il divario di esposizione. Vale il 30,5% in media rispetto alla sola attivazione di HybridLink (Tabella 3)."},{front:"Ricompensa di HybridRL",back:"r(\u03C4) = r_correct + r_format + r_tool. Nessun termine di ricompensa per l'uso latente: l'equilibrio testo/latente emerge e non \xe8 incentivato."},{front:"Il numero dell'intervento causale",back:"Corrompere i pensieri latenti costa il 44,9-51,3% di accuratezza (Tabella 5). Prova che il flusso latente \xe8 portante, e il motivo per cui la lettura per vicino pi\xf9 prossimo non pu\xf2 essere lossless."},{front:"Neuralese",back:"Termine informale per il ragionamento svolto in spazio latente continuo o con calcolo ricorrente senza alcuna traccia di token leggibile da un umano. Il punto d'arrivo verso cui indica il ragionamento latente, e ci\xf2 che preoccupa la ricerca sulla monitorabilit\xe0 della CoT."},{front:"Il sintomo llama.cpp",back:"Generazione infinita su una domanda banale. Il backbone emette <latent>, il runtime non ha HybridLink che prenda il controllo e niente pu\xf2 soddisfare la condizione di chiusura. Non un checkpoint rotto: un componente mancante."}]}),"\n",(0,a.jsx)(i.h2,{id:"dovresti-gi\xe0-occupartene",children:"Dovresti gi\xe0 occupartene?"}),"\n",(0,a.jsx)(i.p,{children:"Risposta onesta per tre lettori diversi."}),"\n",(0,a.jsxs)(i.table,{children:[(0,a.jsx)(i.thead,{children:(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.th,{children:"Se sei\u2026"}),(0,a.jsx)(i.th,{children:"Allora"})]})}),(0,a.jsxs)(i.tbody,{children:[(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:(0,a.jsx)(i.strong,{children:"Chi rilascia un agente su un'API"})}),(0,a.jsxs)(i.td,{children:["Niente da fare oggi. Non esiste un endpoint ospitato di ragionamento latente. La lezione trasferibile \xe8 la diagnosi, non la cura: misura quanta parte della tua fattura sono token di ",(0,a.jsx)(i.em,{children:"deliberazione"})," rispetto ai token di input e di azione. Se la deliberazione domina, questa linea di lavoro punta a te."]})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:(0,a.jsx)(i.strong,{children:"Chi esegue pesi aperti"})}),(0,a.jsx)(i.td,{children:"Vale un pomeriggio, su una macchina con GPU, tramite il motore del repo stesso, e solo quello. Aspettati un artefatto di ricerca: 8B/14B su Qwen3-Base non \xe8 competitivo a livello di frontiera nella chat generale, e i benchmark che contano qui sono ricerca agentica e matematica."})]}),(0,a.jsxs)(i.tr,{children:[(0,a.jsx)(i.td,{children:(0,a.jsx)(i.strong,{children:"Chi fa lavoro di interpretabilit\xe0 o sicurezza"})}),(0,a.jsx)(i.td,{children:"\xc8 la cosa pi\xf9 utile dell'elenco. Un agente latente rilasciato, con licenza MIT, che usa tool, con uno strumento di lettura incluso e un risultato di intervento causale pubblicato, \xe8 un oggetto di studio molto migliore di un'affermazione interna di un laboratorio sul proprio ragionamento nascosto."})]})]})]}),"\n",(0,a.jsxs)(i.p,{children:["Gli scettici nel thread di lancio avevano un altro punto da conservare: la chain-of-thought continua non \xe8 nuova, le architetture di transformer in loop puntano a qualcosa di simile, e i laboratori di frontiera potrebbero benissimo gi\xe0 eseguire in privato varianti di questo. Niente dell'esistenza di HybridAgent ti dice se qualche prodotto in commercio pensi nello spazio latente. Ci\xf2 che dice \xe8 che ",(0,a.jsx)(i.strong,{children:"l'ingegneria non \xe8 pi\xf9 difficile"}),": un adapter da ~10M parametri pi\xf9 due fasi di addestramento, ed \xe8 proprio per questo che la questione della monitorabilit\xe0 smette di essere ipotetica."]}),"\n",(0,a.jsx)(s,{questions:[{q:"Cosa fa davvero HybridLink?",options:["Comprime la KV cache cos\xec gli span latenti occupano meno memoria","Mappa gli stati nascosti dell'ultimo layer nello spazio degli embedding di input tramite una MLP residua a due layer, cos\xec uno stato nascosto pu\xf2 essere reinserito come prossimo input","Instrada tra un piccolo modello latente e un grande modello di testo a seconda della difficolt\xe0 del compito","Traduce i vettori latenti in spiegazioni in linguaggio naturale per l'utente"],answer:1,explain:"e_{t+1} = h_t + W_2\xb7\u03C3(W_1\xb7h_t). Gli stati nello spazio di output e gli embedding nello spazio di input hanno distribuzioni diverse; HybridLink li collega, con il residuo che porta avanti la semantica. ~10M parametri per un backbone da 4B."},{q:"Perch\xe9 caricare HybridAgent-8B in llama.cpp o in Transformers semplice produce generazione infinita?",options:["I checkpoint sono corrotti e vanno riscaricati","La quantizzazione a 8 bit rompe gli embedding dei token \xe0ncora","HybridLink vive in un adapter separato pi\xf9 codice di generazione personalizzato, quindi il backbone emette <latent> e non esiste nulla che reinserisca gli stati nascosti o valuti la condizione di chiusura","Il modello richiede una chiave API Tavily prima di poter generare qualsiasi testo"],answer:2,explain:"La model card afferma chiaramente che il caricamento standard con Transformers produce una variante solo testo. Il comportamento ibrido sta in adapter.pt e nel motore di generazione del repo. Il modello entra in una modalit\xe0 che il runtime non pu\xf2 implementare e non ne esce mai."},{q:"Un agente solo testo spende ~596 token di testo su un compito; HybridAgent-8B ne spende ~302. Cos'altro sta facendo?",options:["Niente: ragiona semplicemente in modo pi\xf9 conciso, ed \xe8 da l\xec che viene tutto il risparmio","170-183 forward pass latenti aggiuntivi che non producono alcun testo","Mette in cache il turno precedente cos\xec da saltare un nuovo ragionamento","Delega il ragionamento restante a un modello pi\xf9 grande"],answer:1,explain:"Non pensa di meno: pensa in un mezzo non fatturato a parola. Un passo latente \xe8 comunque un intero forward pass, quindi il risparmio viene dal saltare decode-and-re-embed, da una sequenza KV pi\xf9 corta e da meno passi totali, non da calcolo gratuito."},{q:"Quale risultato mina di pi\xf9 l'affermazione che i pensieri latenti siano ispezionabili fedelmente come pseudo-testo?",options:["La lettura funziona solo sul checkpoint 14B","Corrompere i pensieri latenti costa il 44,9-51,3% di accuratezza, quindi i vettori portano molto pi\xf9 di quanto il loro singolo token pi\xf9 vicino possa rappresentare","Gli autori non hanno mai pubblicato lo strumento di lettura","La modalit\xe0 latente \xe8 usata solo sui benchmark di matematica"],answer:1,explain:"L'intervento causale prova che il flusso latente \xe8 portante. Una lettura per vicino pi\xf9 prossimo che comprimesse un vettore portante in una parola senza perdere nulla significherebbe che il vettore non ha mai avuto bisogno di essere continuo. Le due affermazioni non possono essere entrambe pienamente vere."},{q:"Quale dei tre approcci di ragionamento latente non richiede alcun addestramento?",options:["Coconut: riordina solo tracce CoT esistenti","HybridAgent: HybridLink \xe8 congelato all'inizializzazione","Soft Thinking: il concept token \xe8 una miscela pesata per probabilit\xe0 di embedding di token esistenti","Tutti e tre richiedono fine-tuning supervisionato"],answer:2,explain:"Soft Thinking (arXiv 2505.15778) \xe8 esplicitamente training-free: costruisce lo stato continuo dalla distribuzione di output del modello stesso sul vocabolario. Coconut richiede addestramento a curriculum; HybridAgent richiede HybridSFT pi\xf9 HybridRL su 8-32 GPU."},{q:"La ricompensa di HybridRL \xe8 r_correct + r_format + r_tool. Cosa c'\xe8 di notevole in quell'elenco?",options:["Penalizza la modalit\xe0 latente, quindi il modello la usa con parsimonia","Non c'\xe8 alcun termine di ricompensa per l'uso latente: l'equilibrio testo/latente \xe8 emergente","Premia direttamente output pi\xf9 brevi, ed \xe8 da l\xec che viene la riduzione dei token","Include un termine di monitorabilit\xe0 che mantiene i pensieri leggibili"],answer:1,explain:"Nessuna ricompensa sull'uso della modalit\xe0. Gli autori lasciano che l'equilibrio nasca dall'ottimizzazione di correttezza, formato e uso dei tool, il che significa anche che la riduzione dei token \xe8 un effetto collaterale della policy appresa e non qualcosa su cui si \xe8 addestrato direttamente."}]}),"\n",(0,a.jsx)(i.h2,{id:"fonti-e-approfondimenti",children:"Fonti e approfondimenti"}),"\n",(0,a.jsxs)(i.ul,{children:["\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"https://arxiv.org/abs/2610.18861",children:"Hybrid Reasoning Agents (arXiv 2610.18861)"})," \u2014 Zou, Qi, Chen, Bianchi, Zhu, Lu, He, Zou; inviato il 13 ottobre 2026. La formula di HybridLink, la memoria di lavoro continua, HybridSFT/HybridRL, gli 11 benchmark, l'ablazione dell'auto-condizionamento (Tabella 3) e gli interventi causali (Tabella 5)."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"https://github.com/togethercomputer/HybridAgent",children:"togethercomputer/HybridAgent"})," \u2014 MIT. Motore di inferenza, pipeline SFT e RL, il viewer ",(0,a.jsx)(i.code,{children:"interpretable_latent_mode"})," e i requisiti GPU (8-16 per SFT, 32 su 4 nodi per RL)."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"https://huggingface.co/togethercomputer/HybridAgent-8B-Agentic",children:"togethercomputer/HybridAgent-8B-Agentic"})," e ",(0,a.jsx)(i.a,{href:"https://huggingface.co/togethercomputer/HybridAgent-14B-Agentic",children:"-14B-Agentic"}),' \u2014 i checkpoint, su Qwen3-8B-Base e Qwen3-14B-Base. La model card \xe8 dove vive l\'avviso "standard Transformers loading yields a text-only variant".']}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"https://huggingface.co/papers/2610.18861",children:"Pagina del paper su Hugging Face"})," \u2014 artefatti collegati, inclusi i dataset di addestramento ",(0,a.jsx)(i.code,{children:"HybridAgent-HybridSFT-v1/-v2"})," e ",(0,a.jsx)(i.code,{children:"HybridAgent-HybridRL"}),"."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"https://arxiv.org/abs/2412.06769",children:"Training Large Language Models to Reason in a Continuous Latent Space (arXiv 2412.06769)"})," \u2014 Coconut, Meta FAIR. L'origine della chain-of-continuous-thought, il risultato di BFS emergente e il risultato che un classificatore appreso per il cambio di modalit\xe0 non andava meglio di un budget latente fisso."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"https://arxiv.org/abs/2505.15778",children:"Soft Thinking: Unlocking the Reasoning Potential of LLMs in Continuous Concept Space (arXiv 2505.15778)"})," \u2014 l'alternativa training-free: miscele di embedding pesate per probabilit\xe0 come concept token, pi\xf9 Cold Stop."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"https://arxiv.org/abs/2507.11473",children:"Chain of Thought Monitorability: A New and Fragile Opportunity for AI Safety (arXiv 2507.11473)"})," \u2014 il position paper intra-laboratorio (41 autori; tra loro Bengio, Dragan, Hendrycks) sul perch\xe9 il ragionamento leggibile \xe8 un'opportunit\xe0 di supervisione e perch\xe9 le scelte di architettura possono distruggerla in silenzio."]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"https://news.ycombinator.com/item?id=50145337",children:"Discussione su Hacker News, 19 ottobre 2026"}),' \u2014 396 punti, 192 commenti. Fonte per le segnalazioni pratiche di fallimento (loop su "who is the pope?", llama.cpp a 8 e 16 bit), l\'obiezione sulla lettura per vicino pi\xf9 prossimo e l\'inquadramento "Most Forbidden Technique".']}),"\n",(0,a.jsxs)(i.li,{children:["Compagni AILmanac: ",(0,a.jsx)(i.a,{href:"/docs/models/why-agents-burn-tokens",children:"Why AI agents burn tokens"})," \xb7 ",(0,a.jsx)(i.a,{href:"/docs/models/reasoning-models-compared",children:"Reasoning models compared"})," \xb7 ",(0,a.jsx)(i.a,{href:"/docs/frontiers/reward-hacking-in-coding-agents",children:"Reward hacking in coding agents"})]}),"\n"]}),"\n",(0,a.jsx)(i.h2,{id:"prossimi-passi",children:"Prossimi passi"}),"\n",(0,a.jsxs)(i.ul,{children:["\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"/docs/models/why-agents-burn-tokens",children:"Why AI agents burn tokens (and how to cap the bill)"})," \u2014 il problema che il ragionamento latente attacca, misurato su modelli che puoi davvero chiamare oggi"]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"/docs/models/diffusion-llms-parallel-text",children:"Diffusion LLMs: the models that don't write left to right"})," \u2014 l'altro tentativo attuale di cambiare il ciclo di decodifica stesso invece del modello al suo interno"]}),"\n",(0,a.jsxs)(i.li,{children:[(0,a.jsx)(i.a,{href:"/docs/frontiers/reward-hacking-in-coding-agents",children:"Reward hacking in coding agents"})," \u2014 cosa va storto quando ottimizzi contro ci\xf2 che puoi osservare, che \xe8 la met\xe0 in fase di addestramento del problema della monitorabilit\xe0"]}),"\n"]})]})}function p(e={}){let{wrapper:i}={...(0,t.R)(),...e.components};return i?(0,a.jsx)(i,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}function u(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}},28453(e,i,n){n.d(i,{R:()=>r,x:()=>l});var o=n(96540);let a={},t=o.createContext(a);function r(e){let i=o.useContext(t);return o.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function l(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),o.createElement(t.Provider,{value:i},e.children)}}}]);